class Solution {
  private static int gcd(int a, int b) {
    while (b != 0) {
      int t = a % b;
      a = b;
      b = t;
    }
    return a;
  }

  public int countGoodSubseq(int[] nums, int p, int[][] queries) {
    int n = nums.length, size = 1;
    while (size < n) size <<= 1;
    int[] tree = new int[2 * size];
    int divisible = 0;
    for (int i = 0; i < n; i++) {
      if (nums[i] % p == 0) {
        tree[size + i] = nums[i];
        divisible++;
      }
    }
    for (int i = size - 1; i >= 1; i--) tree[i] = gcd(tree[2 * i], tree[2 * i + 1]);
    int good = 0;
    for (int[] q : queries) {
      int idx = q[0], val = q[1];
      if (nums[idx] % p == 0) divisible--;
      nums[idx] = val;
      int leaf = size + idx;
      tree[leaf] = 0;
      if (val % p == 0) {
        tree[leaf] = val;
        divisible++;
      }
      for (leaf >>= 1; leaf >= 1; leaf >>= 1) tree[leaf] = gcd(tree[2 * leaf], tree[2 * leaf + 1]);
      if (divisible == 0 || tree[1] != p) continue;
      if (divisible < n) {
        good++;
        continue;
      }
      if (n >= 7) {
        good++;
        continue;
      }
      boolean found = false;
      for (int skip = 0; skip < n && !found; skip++) {
        int g = 0;
        for (int j = 0; j < n; j++) if (j != skip) g = gcd(g, nums[j]);
        if (g == p) found = true;
      }
      if (found) good++;
    }
    return good;
  }
}
